     */
    'terms' => [
        'title' => "Onze gebruiksvoorwaarden",
        'updated' => "Laatste wijziging: :date",
        'updatedOn' => "20 november 2026",

        'sections' => [
            [
                'title' => "Reikwijdte van de dienst",
                'blocks' => [
                    ['text' => "Monica ondersteunt de volgende browsers:"],
                    ['items' => [
